const APP_AUDITORIAS_GAS_URL = "https://script.google.com/macros/s/AKfycbylJ9W5lSuvTvE600uoNc53zkl7v4-Mn1T6pnfoyEKHguteV8ALLwOOPCRP_zFgVq9V/exec";

async function appGasPost(payload) {
    const accion = String((payload && payload.accion) || "POST");
    const body = new URLSearchParams();
    body.set("payload", JSON.stringify(payload || {}));
    let r;
    try {
        r = await fetch(APP_AUDITORIAS_GAS_URL, {
            method: "POST",
            body,
            redirect: "follow",
            cache: "no-store"
        });
    } catch (err) {
        throw new Error("No se pudo conectar con la BBDD (" + accion + "): " + (err.message || err));
    }

    const text = await r.text();
    let data;
    try { data = JSON.parse(text); } catch (_) {
        const preview = String(text || "").replace(/\s+/g, " ").slice(0, 700);
        const looksHtml = /<html|<!doctype html/i.test(text);
        if (looksHtml) {
            throw new Error(
                "La BBDD respondió con HTML en la acción '" + accion + "' (HTTP " + r.status + "). " +
                "La petición POST no ha devuelto el JSON esperado. Es posible que el payload sea demasiado grande o que Google haya rechazado/redirigido la petición. Respuesta: " + preview
            );
        }
        throw new Error("Respuesta no válida de la BBDD en '" + accion + "' (HTTP " + r.status + "): " + preview);
    }
    if (!data.ok) throw new Error((data.error || "La BBDD devolvió un error.") + " [acción: " + accion + "]");
    return data;
}

/*
 * Las fotografías no se envían dentro de guardarAuditoria.
 * Esto evita que una auditoría con muchas fotos convierta el POST principal
 * en un payload enorme. Cada fotografía se envía en una petición independiente.
 */
function prepararAuditoriaParaSincronizacion(auditoria) {
    const fotos = [];
    let contador = 0;

    function clonar(valor, contexto) {
        if (Array.isArray(valor)) return valor.map(v => clonar(v, contexto));
        if (!valor || typeof valor !== "object") return valor;

        const contextoLocal = {
            modulo: String(valor.modulo || valor.origen || contexto.modulo || "GENERAL"),
            incidenciaId: String(valor.incidenciaId || contexto.incidenciaId || "")
        };
        const out = {};

        Object.keys(valor).forEach(k => {
            const v = valor[k];
            if ((k === "dataUrl" || k === "base64" || k === "imagen") && typeof v === "string" && /^data:image\//i.test(v)) {
                contador++;
                fotos.push({
                    dataUrl: v,
                    modulo: contextoLocal.modulo,
                    incidenciaId: contextoLocal.incidenciaId,
                    indice: contador,
                    nombreSugerido: valor.nombre || valor.nombreArchivo || ""
                });
                return;
            }
            out[k] = clonar(v, contextoLocal);
        });
        return out;
    }

    const auditoriaLimpia = clonar(auditoria, {modulo:"GENERAL", incidenciaId:""});
    return { auditoria: auditoriaLimpia, fotografias: fotos };
}

async function sincronizarFotografiasAuditoria(auditoriaId, tipo, fotografias) {
    const lista = Array.isArray(fotografias) ? fotografias : [];
    let guardadas = 0;
    for (let i = 0; i < lista.length; i++) {
        const f = lista[i];
        if (!f || !f.dataUrl) continue;
        try {
            await appGasPost({
                accion: "guardarFotografia",
                auditoriaId: auditoriaId,
                tipo: tipo || "AUDITORIA",
                modulo: f.modulo || tipo || "GENERAL",
                incidenciaId: f.incidenciaId || "",
                indice: f.indice || (i + 1),
                nombreSugerido: f.nombreSugerido || "",
                dataUrl: f.dataUrl
            });
            guardadas++;
        } catch (_) {
            try {
                const ver = await verificarFotografiasRemotas(auditoriaId);
                if (ver && Number(ver.count || 0) >= i + 1) guardadas++;
            } catch (__) {}
        }
    }
    return guardadas;
}

async function verificarFotografiasRemotas(auditoriaId) {
    return appGasGet({ accion: "verificarFotografias", auditoriaId });
}

async function guardarAuditoriaYFotografias(tipo, auditoria) {
    const preparado = prepararAuditoriaParaSincronizacion(auditoria);
    const copia = preparado.auditoria;

    // La auditoría se guarda primero. Si esta operación falla, no continuamos.
    const resultado = await appGasPost({
        accion: "guardarAuditoria",
        tipo: tipo,
        auditoria: copia
    });

    // Las fotografías son independientes: si una falla, no debemos perder ni
    // la auditoría ni el resto de fotografías ni impedir la generación del PDF.
    let fotografiasGuardadas = 0;
    const erroresFotografias = [];
    for (let i = 0; i < preparado.fotografias.length; i++) {
        const f = preparado.fotografias[i];
        try {
            await appGasPost({
                accion: "guardarFotografia",
                auditoriaId: auditoria && auditoria.id ? auditoria.id : "",
                tipo: tipo || "AUDITORIA",
                modulo: f.modulo || tipo || "GENERAL",
                incidenciaId: f.incidenciaId || "",
                indice: f.indice || (i + 1),
                nombreSugerido: f.nombreSugerido || "",
                dataUrl: f.dataUrl
            });
            fotografiasGuardadas++;
        } catch (e) {
            let confirmada = false;
            try {
                const ver = await verificarFotografiasRemotas(auditoria && auditoria.id ? auditoria.id : "");
                // Como las fotografías se envían en orden, si el servidor ya
                // registra al menos i+1 para esta auditoría, la fotografía que
                // provocó la respuesta no válida sí llegó a guardarse.
                confirmada = !!(ver && Number(ver.count || 0) >= i + 1);
            } catch (_) {}

            if (confirmada) {
                fotografiasGuardadas++;
            } else {
                erroresFotografias.push({
                    indice: f.indice || (i + 1),
                    modulo: f.modulo || tipo || "GENERAL",
                    error: e && e.message ? e.message : String(e)
                });
            }
        }
    }

    return {
        resultado,
        fotografiasGuardadas,
        fotografiasTotales: preparado.fotografias.length,
        erroresFotografias
    };
}

async function appGasGet(payload) {
    const params = new URLSearchParams(payload || {});
    const url = APP_AUDITORIAS_GAS_URL + (APP_AUDITORIAS_GAS_URL.includes("?") ? "&" : "?") + params.toString();
    const r = await fetch(url, { method: "GET", cache: "no-store" });
    const text = await r.text();
    let data;
    try { data = JSON.parse(text); } catch (_) {
        const looksHtml = /^\s*<!doctype html|^\s*<html/i.test(text);
        throw new Error(looksHtml
            ? "La BBDD ha devuelto una respuesta no válida al consultar las estadísticas. Compruebe la conexión con la BBDD."
            : "Respuesta no válida de la BBDD: " + text.slice(0, 300));
    }
    if (!data.ok) throw new Error(data.error || "La BBDD devolvió un error.");
    return data;
}

async function blobADataUrl(blob) {
    return await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ""));
        reader.onerror = () => reject(reader.error || new Error("No se pudo convertir el PDF."));
        reader.readAsDataURL(blob);
    });
}

async function guardarPdfEnDrive(blob, auditoriaId, tipo, nombre) {
    const dataUrl = await blobADataUrl(blob);
    try {
        return await appGasPost({ accion:"guardarInformePdf", auditoriaId, tipo, nombre, mimeType:"application/pdf", base64:dataUrl });
    } catch (e) {
        // Apps Script puede completar la creación del archivo y devolver una
        // respuesta HTML al navegador. Verificamos el registro antes de
        // informar de un falso fallo del PDF.
        try {
            const ver = await appGasGet({ accion: "verificarInformePdf", auditoriaId, nombre });
            if (ver && ver.encontrado) return ver;
        } catch (_) {}
        throw e;
    }
}

async function cargarEstadisticasEmpresas() {
    return appGasGet({ accion: "obtenerEstadisticas" });
}

async function diagnosticoGoogleAppsScript() {
    const resultado = { conexion: "PENDIENTE", estadisticas: "PENDIENTE", guardado: "NO PROBADO", fotografias: "NO PROBADO", pdf: "NO PROBADO" };
    try {
        await appGasGet({ accion: "comprobarConexion" });
        resultado.conexion = "OK";
    } catch (e) { resultado.conexion = "ERROR: " + (e.message || e); }
    try {
        const d = await appGasGet({ accion: "obtenerEstadisticas" });
        resultado.estadisticas = d && d.ok ? "OK" : "ERROR";
    } catch (e) { resultado.estadisticas = "ERROR: " + (e.message || e); }
    console.table(resultado);
    return resultado;
}

function escStats(v) { return escaparValorResumen(v == null ? "" : String(v)); }

let _estadisticasActuales = null;
let _estadisticasFiltros = { empresa: "", provincia: "", proyecto: "", fechaDesde: "", fechaHasta: "", tipo: "", estado: "", incidencias: "" };

function normalizarTextoEstadisticas(v) {
    return String(v == null ? "" : v).replace(/\s+/g, " ").trim().toLowerCase();
}

function fechaEstadisticaToDate(v) { const s=String(v||'').trim(); if(!s) return null; const d=new Date(s+'T00:00:00'); return isNaN(d.getTime())?null:d; }
function filtrarDetalleEstadisticas() {
    const d=_estadisticasActuales||{}; const rows=Array.isArray(d.detalleAuditorias)?d.detalleAuditorias:[]; const f=_estadisticasFiltros||{};
    const desde=fechaEstadisticaToDate(f.fechaDesde), hasta=fechaEstadisticaToDate(f.fechaHasta);
    return rows.filter(r=>{
        if(f.empresa && !normalizarTextoEstadisticas(r.empresa).includes(normalizarTextoEstadisticas(f.empresa))) return false;
        if(f.provincia && !normalizarTextoEstadisticas(r.provincia).includes(normalizarTextoEstadisticas(f.provincia))) return false;
        if(f.proyecto && !normalizarTextoEstadisticas(r.proyecto).includes(normalizarTextoEstadisticas(f.proyecto))) return false;
        if(f.tipo && normalizarTextoEstadisticas(r.tipo)!==normalizarTextoEstadisticas(f.tipo)) return false;
        if(f.estado && normalizarTextoEstadisticas(r.estado)!==normalizarTextoEstadisticas(f.estado)) return false;
        if(f.incidencias==='con' && Number(r.incidencias||0)<=0) return false;
        if(f.incidencias==='sin' && Number(r.incidencias||0)>0) return false;
        const fd=fechaEstadisticaToDate(r.fecha); if(desde && (!fd || fd<desde)) return false; if(hasta && (!fd || fd>hasta)) return false;
        return true;
    });
}
function obtenerEmpresasFiltradasEstadisticas(){
    const rows=filtrarDetalleEstadisticas(), map={};
    rows.forEach(x=>{const k=normalizarTextoEstadisticas(x.empresa); if(!k)return; if(!map[k])map[k]={empresa:x.empresa,auditorias:0,correctas:0,conIncidencias:0,trabajadores:new Set(),ultima:''}; const e=map[k]; e.auditorias++; if(Number(x.incidencias||0)>0)e.conIncidencias++;else e.correctas++; if(x.trabajador)e.trabajadores.add(normalizarTextoEstadisticas(x.trabajador)); if(!e.ultima||x.fecha>e.ultima)e.ultima=x.fecha;});
    return Object.values(map).map(e=>({empresa:e.empresa,auditorias:e.auditorias,correctas:e.correctas,conIncidencias:e.conIncidencias,trabajadores:e.trabajadores.size,ultima:e.ultima})).sort((a,b)=>b.auditorias-a.auditorias||a.empresa.localeCompare(b.empresa));
}
function obtenerProvinciasFiltradasEstadisticas(){
    const rows=filtrarDetalleEstadisticas(), map={};
    rows.forEach(x=>{const k=normalizarTextoEstadisticas(x.provincia); if(!k)return; if(!map[k])map[k]={provincia:x.provincia,auditorias:0,correctas:0,conIncidencias:0}; const e=map[k];e.auditorias++;if(Number(x.incidencias||0)>0)e.conIncidencias++;else e.correctas++;});
    return Object.values(map).sort((a,b)=>b.auditorias-a.auditorias||a.provincia.localeCompare(b.provincia));
}

function aplicarFiltrosEstadisticas() {
    const get = id => document.getElementById(id);
    _estadisticasFiltros = {
        empresa: get("statsFiltroEmpresa") ? get("statsFiltroEmpresa").value : "",
        provincia: get("statsFiltroProvincia") ? get("statsFiltroProvincia").value : "",
        proyecto: get("statsFiltroProyecto") ? get("statsFiltroProyecto").value : "",
        fechaDesde: get("statsFiltroFechaDesde") ? get("statsFiltroFechaDesde").value : "",
        fechaHasta: get("statsFiltroFechaHasta") ? get("statsFiltroFechaHasta").value : "",
        tipo: get("statsFiltroTipo") ? get("statsFiltroTipo").value : "",
        estado: get("statsFiltroEstado") ? get("statsFiltroEstado").value : "",
        incidencias: get("statsFiltroIncidencias") ? get("statsFiltroIncidencias").value : ""
    };
    renderTablasEstadisticas();
}

function limpiarFiltrosEstadisticas() {
    _estadisticasFiltros = { empresa: "", provincia: "", proyecto: "", fechaDesde: "", fechaHasta: "", tipo: "", estado: "", incidencias: "" };
    ["statsFiltroEmpresa","statsFiltroProvincia","statsFiltroProyecto","statsFiltroFechaDesde","statsFiltroFechaHasta","statsFiltroTipo","statsFiltroEstado","statsFiltroIncidencias"].forEach(id => {
        const el = document.getElementById(id); if (el) el.value = "";
    });
    renderTablasEstadisticas();
}

function renderTablasEstadisticas() {
    const host = document.getElementById("statsTablasHost");
    if (!host) return;
    const empresas = obtenerEmpresasFiltradasEstadisticas();
    const provincias = obtenerProvinciasFiltradasEstadisticas();
    const detalle = filtrarDetalleEstadisticas();

    const empresaRows = empresas.map(x => `<tr><td class="stats-text">${escStats(x.empresa)}</td><td class="stats-num">${Number(x.auditorias || 0)}</td><td class="stats-num">${Number(x.correctas || 0)}</td><td class="stats-num">${Number(x.conIncidencias || 0)}</td><td class="stats-num">${Number(x.trabajadores || 0)}</td><td class="stats-date">${escStats(x.ultima || "")}</td></tr>`).join("") || `<tr><td colspan="6" class="stats-empty">No hay datos para los filtros seleccionados.</td></tr>`;
    const provRows = provincias.map(x => `<tr><td class="stats-text">${escStats(x.provincia)}</td><td class="stats-num">${Number(x.auditorias || 0)}</td><td class="stats-num">${Number(x.correctas || 0)}</td><td class="stats-num">${Number(x.conIncidencias || 0)}</td></tr>`).join("") || `<tr><td colspan="4" class="stats-empty">No hay datos para los filtros seleccionados.</td></tr>`;
    const detalleRows = detalle.map(x => `<tr><td class="stats-text">${escStats(x.id)}</td><td class="stats-date">${escStats(x.fecha)}</td><td>${escStats(x.tipo)}</td><td class="stats-text">${escStats(x.auditor)}</td><td class="stats-text">${escStats(x.empresa)}</td><td class="stats-text">${escStats(x.proyecto)}</td><td class="stats-text">${escStats(x.trabajador)}</td><td class="stats-text">${escStats(x.dni)}</td><td>${escStats(x.estado)}</td><td class="stats-num">${Number(x.incidencias || 0)}</td><td class="stats-text">${escStats(x.provincia)}</td><td><button type="button" class="secondary-button" onclick="abrirAuditoriaRecuperada('${String(x.id||'').replace(/'/g,"\'")}')">📂 Abrir</button></td></tr>`).join("") || `<tr><td colspan="12" class="stats-empty">No hay auditorías para los filtros seleccionados.</td></tr>`;
    const idsFiltrados=new Set(detalle.map(x=>String(x.id)));
    const globalIncumplimientos=Array.isArray((_estadisticasActuales||{}).incumplimientos)?_estadisticasActuales.incumplimientos:[];
    const incumplimientos=globalIncumplimientos.length
      ? globalIncumplimientos.filter(x=>idsFiltrados.has(String(x.idAuditoria)))
      : detalle.flatMap(x=>Array.isArray(x.incumplimientos)?x.incumplimientos.map(i=>Object.assign({idAuditoria:x.id,fechaAuditoria:x.fecha,proyecto:x.proyecto,empresa:x.empresa,provincia:x.provincia,tipo:x.tipo,auditor:x.auditor,trabajador:x.trabajador,dni:x.dni},i)):[]);
    const incumRows=incumplimientos.map(x=>`<tr><td class="stats-text">${escStats(x.idAuditoria)}</td><td class="stats-date">${escStats(x.fechaAuditoria)}</td><td class="stats-text">${escStats(x.proyecto)}</td><td class="stats-text">${escStats(x.empresa)}</td><td>${escStats(x.modulo)}</td><td>${escStats(x.apartado)}</td><td class="stats-text">${escStats(x.control)}</td><td class="stats-text">${escStats(x.descripcion)}</td><td>${escStats(x.estado)}</td><td class="stats-text">${escStats(x.responsable)}</td><td>${escStats(x.fechaPrevista)}</td><td>${escStats(x.fechaCierre)}</td><td>—</td></tr>`).join("") || `<tr><td colspan="13" class="stats-empty">No hay incumplimientos para los filtros seleccionados.</td></tr>`;

    host.innerHTML = `
      <div class="card stats-card">
        <div class="stats-section-title"><div><h3>Resumen por empresa</h3><small>${empresas.length} empresas</small></div></div>
        <div class="table-responsive stats-table-wrap"><table class="stats-table"><thead><tr><th>Empresa</th><th>Auditorías</th><th>Correctas</th><th>Con incidencias</th><th>Trabajadores</th><th>Última auditoría</th></tr></thead><tbody>${empresaRows}</tbody></table></div>
      </div>
      <div class="card stats-card">
        <div class="stats-section-title"><div><h3>Resumen por provincia</h3><small>${provincias.length} provincias</small></div></div>
        <div class="table-responsive stats-table-wrap"><table class="stats-table"><thead><tr><th>Provincia</th><th>Auditorías</th><th>Correctas</th><th>Con incidencias</th></tr></thead><tbody>${provRows}</tbody></table></div>
      </div>
      <div class="card stats-card">
        <div class="stats-section-title"><div><h3>Detalle de auditorías</h3><small>${detalle.length} registros mostrados</small></div></div>
        <div class="table-responsive stats-table-wrap"><table class="stats-table stats-detail-table"><thead><tr><th>ID auditoría</th><th>Fecha</th><th>Tipo</th><th>Auditor</th><th>Empresa</th><th>Proyecto</th><th>Trabajador</th><th>DNI/NIE</th><th>Estado</th><th>Incidencias</th><th>Provincia</th><th>Acciones</th></tr></thead><tbody>${detalleRows}</tbody></table></div>
      </div>
      <div class="card stats-card">
        <div class="stats-section-title"><div><h3>Detalle de incumplimientos por auditoría</h3><small>${incumplimientos.length} incumplimientos mostrados</small></div></div>
        <div class="table-responsive stats-table-wrap"><table class="stats-table stats-detail-table"><thead><tr><th>ID auditoría</th><th>Fecha</th><th>Proyecto</th><th>Empresa</th><th>Módulo</th><th>Apartado</th><th>Control</th><th>Incumplimiento</th><th>Estado</th><th>Responsable</th><th>Fecha prevista</th><th>Fecha cierre</th><th>Evidencias</th></tr></thead><tbody>${incumRows}</tbody></table></div>
      </div>`;
}

function exportarEstadisticasExcel() {
    if (typeof XLSX === "undefined") {
        alert("No se ha cargado el componente de exportación Excel. Recargue la aplicación e inténtelo de nuevo.");
        return;
    }
    const empresas = obtenerEmpresasFiltradasEstadisticas();
    const provincias = obtenerProvinciasFiltradasEstadisticas();
    const detalle = filtrarDetalleEstadisticas();
    const wb = XLSX.utils.book_new();

    const wsEmp = XLSX.utils.json_to_sheet(empresas.map(x => ({
        "Empresa": x.empresa, "Auditorías": Number(x.auditorias || 0), "Correctas": Number(x.correctas || 0),
        "Con incidencias": Number(x.conIncidencias || 0), "Trabajadores": Number(x.trabajadores || 0), "Última auditoría": x.ultima || ""
    })));
    const wsProv = XLSX.utils.json_to_sheet(provincias.map(x => ({
        "Provincia": x.provincia, "Auditorías": Number(x.auditorias || 0), "Correctas": Number(x.correctas || 0), "Con incidencias": Number(x.conIncidencias || 0)
    })));
    const wsDet = XLSX.utils.json_to_sheet(detalle.map(x => ({
        "ID auditoría": x.id, "Fecha": x.fecha, "Tipo": x.tipo, "Auditor": x.auditor, "Empresa": x.empresa, "Proyecto": x.proyecto,
        "Trabajador": x.trabajador, "DNI/NIE": x.dni, "Estado": x.estado, "Incidencias": Number(x.incidencias || 0), "Provincia": x.provincia
    })));

    const idsFiltradosExcel = new Set(detalle.map(x => String(x.id)));
    const globalIncumplimientosExcel = Array.isArray((_estadisticasActuales || {}).incumplimientos) ? _estadisticasActuales.incumplimientos : [];
    const incumplimientosExcel = globalIncumplimientosExcel.length
      ? globalIncumplimientosExcel.filter(x => idsFiltradosExcel.has(String(x.idAuditoria)))
      : detalle.flatMap(x => Array.isArray(x.incumplimientos) ? x.incumplimientos.map(i => Object.assign({idAuditoria:x.id,fechaAuditoria:x.fecha,proyecto:x.proyecto,empresa:x.empresa,provincia:x.provincia,tipo:x.tipo,auditor:x.auditor,trabajador:x.trabajador,dni:x.dni}, i)) : []);
    const wsInc = XLSX.utils.json_to_sheet(incumplimientosExcel.map(x => ({
        "ID auditoría": x.idAuditoria, "Fecha auditoría": x.fechaAuditoria, "Proyecto": x.proyecto, "Empresa": x.empresa, "Provincia": x.provincia,
        "Tipo": x.tipo, "Auditor": x.auditor, "Trabajador": x.trabajador, "DNI/NIE": x.dni, "Módulo": x.modulo,
        "Apartado": x.apartado, "Control": x.control, "Incumplimiento": x.descripcion, "Estado": x.estado,
        "Fecha incidencia": x.fechaIncidencia, "Responsable": x.responsable, "Fecha cierre": x.fechaCierre, "Medida correctora": x.medida, "Fecha prevista cierre": x.fechaPrevista, "Observaciones cierre": x.observacionesCierre, "Verificador": x.verificador,
        "Nº evidencias": Number(x.evidencias?.length || 0), "Evidencias": (x.evidencias||[]).map(e=>e.url||'').filter(Boolean).join(' | ')
    })));

    [
        [wsEmp, "Por Empresa"], [wsProv, "Por Provincia"], [wsDet, "Auditorías"], [wsInc, "Incumplimientos"]
    ].forEach(([ws, name]) => {
        const ref = ws['!ref'];
        if (ref) ws['!autofilter'] = { ref };
        ws['!freeze'] = { xSplit: 0, ySplit: 1 };
        XLSX.utils.book_append_sheet(wb, ws, name);
    });
    const fecha = new Date().toISOString().slice(0,10).replace(/-/g, "");
    XLSX.writeFile(wb, `Estadisticas_Auditorias_SPM_${fecha}.xlsx`, { compression: true });
}

function renderDashboardEstadisticas(data) {
    const d = data || {};
    _estadisticasActuales = d;
    _estadisticasFiltros = { empresa: "", provincia: "", proyecto: "", fechaDesde: "", fechaHasta: "", tipo: "", estado: "", incidencias: "" };
    const total = Number(d.totalAuditorias || 0);
    const cards = [
      ["📋", "Auditorías", total], ["🚐", "Vehículos", Number(d.vehiculos || 0)],
      ["🏗️", "Campo", Number(d.campo || 0)], ["⚠️", "Con incidencias", Number(d.conIncidencias || 0)],
      ["👷", "Trabajadores", Number(d.totalTrabajadores || 0)], ["🏢", "Empresas", Number(d.empresas || 0)]
    ].map(x => `<div class="card stats-kpi-card"><div class="stats-kpi-icon">${x[0]}</div><strong>${escStats(x[1])}</strong><div class="stats-kpi-value">${x[2]}</div></div>`).join("");
    return `<div class="dashboard-header"><div><h2>Estadísticas de auditorías</h2><p>Datos consolidados desde la BBDD. Las tablas se filtran desde los controles superiores y pueden exportarse a Excel.</p></div><div class="stats-header-actions"><button type="button" class="primary-button" onclick="exportarEstadisticasExcel()">⬇ Descargar Excel</button><button type="button" class="primary-button" onclick="recuperarAuditoriaPorId()">📂 Recuperar auditoría por ID</button><button type="button" class="secondary-button" onclick="mostrarPantalla('auditoriasInicio')">← Menú principal</button></div></div>
      <div class="module-grid stats-kpi-grid">${cards}</div>
      <div class="card stats-filters-card"><div class="stats-section-title"><div><h3>Filtros</h3><small>Los filtros afectan a las tablas y al Excel descargado.</small></div><button type="button" class="secondary-button" onclick="limpiarFiltrosEstadisticas()">Limpiar filtros</button></div><div class="stats-filters-grid">
        <label>Empresa<input id="statsFiltroEmpresa" type="text" placeholder="Buscar empresa…" oninput="aplicarFiltrosEstadisticas()"></label>
        <label>Provincia<input id="statsFiltroProvincia" type="text" placeholder="Buscar provincia…" oninput="aplicarFiltrosEstadisticas()"></label>
        <label>Proyecto<input id="statsFiltroProyecto" type="text" placeholder="Buscar proyecto…" oninput="aplicarFiltrosEstadisticas()"></label>
        <label>Fecha desde<input id="statsFiltroFechaDesde" type="date" onchange="aplicarFiltrosEstadisticas()"></label>
        <label>Fecha hasta<input id="statsFiltroFechaHasta" type="date" onchange="aplicarFiltrosEstadisticas()"></label>
        <label>Tipo<select id="statsFiltroTipo" onchange="aplicarFiltrosEstadisticas()"><option value="">Todos</option><option value="VEHICULOS_EQUIPOS">Vehículos / EPIs</option><option value="CAMPO">Auditoría de Campo</option></select></label>
        <label>Estado<select id="statsFiltroEstado" onchange="aplicarFiltrosEstadisticas()"><option value="">Todos</option><option value="FINALIZADA">Finalizada</option><option value="BORRADOR">Borrador</option></select></label>
        <label>Incidencias<select id="statsFiltroIncidencias" onchange="aplicarFiltrosEstadisticas()"><option value="">Todas</option><option value="con">Con incidencias</option><option value="sin">Sin incidencias</option></select></label>
      </div></div>
      <div id="statsTablasHost"></div>`;
}

async function abrirDashboardEstadisticas() {
    const sec = document.getElementById("dashboardEstadisticas");
    if (!sec) return;
    sec.innerHTML = `<div class="dashboard-header"><div><h2>Estadísticas de auditorías</h2><p>Cargando datos de la BBDD…</p></div><button type="button" class="secondary-button" onclick="mostrarPantalla('auditoriasInicio')">← Menú</button></div><div class="card">Consultando datos…</div>`;
    mostrarPantalla("dashboardEstadisticas");
    try { const data = await cargarEstadisticasEmpresas(); sec.innerHTML = renderDashboardEstadisticas(data); renderTablasEstadisticas(); }
    catch(e) { sec.innerHTML = `<div class="card"><h3>No se pudieron cargar las estadísticas</h3><p>${escStats(e.message || e)}</p><button class="secondary-button" onclick="abrirDashboardEstadisticas()">Reintentar</button></div>`; }
}

function abrirPanelEmpresas() {
    const sec = document.getElementById("dashboardEstadisticas");
    if (!sec) return;
    cargarEstadisticasEmpresas().then(d => {
      const rows=(d.porEmpresa||[]).map(x=>`<tr><td>${escStats(x.empresa)}</td><td>${x.auditorias}</td><td>${x.trabajadores}</td><td>${x.correctas}</td><td>${x.conIncidencias}</td><td>${escStats(x.ultima||"")}</td></tr>`).join("") || `<tr><td colspan="6">No hay empresas.</td></tr>`;
      sec.innerHTML=`<div class="dashboard-header"><div><h2>Empresas</h2><p>Catálogo generado automáticamente a partir de los formularios.</p></div><button class="secondary-button" onclick="abrirDashboardEstadisticas()">← Estadísticas</button></div><div class="card"><div class="table-responsive"><table style="width:100%;border-collapse:collapse"><thead><tr><th>Empresa</th><th>Auditorías</th><th>Trabajadores</th><th>Correctas</th><th>Con incidencias</th><th>Última auditoría</th></tr></thead><tbody>${rows}</tbody></table></div></div>`;
    }).catch(e=>alert("No se pudieron cargar las empresas: "+(e.message||e)));
}

