/* =========================================================
   V18 — RECUPERACIÓN CENTRALIZADA DESDE BBDD Y DOCUMENTOS EPI
   ========================================================= */

function prepararAuditoriaRecuperada(datos) {
    if (!datos || typeof datos !== "object") throw new Error("La BBDD no devolvió una auditoría válida.");
    const actual = JSON.parse(JSON.stringify(auditoria));
    const recuperada = JSON.parse(JSON.stringify(datos));
    Object.assign(auditoria, actual, recuperada);
    auditoria.id = String(recuperada.id || auditoria.id);
    auditoria.estado = recuperada.estado || "EN_CURSO";
    auditoria.datosGenerales = Object.assign({}, actual.datosGenerales || {}, recuperada.datosGenerales || recuperada.datos || {});
    auditoria.modulos = Object.assign({}, actual.modulos || {}, recuperada.modulos || {});
    auditoria.incidencias = Array.isArray(recuperada.incidencias) ? recuperada.incidencias : [];
    auditoria.fotografias = Array.isArray(recuperada.fotografias) ? recuperada.fotografias : [];
    auditoria.firmas = Object.assign({}, actual.firmas || {}, recuperada.firmas || {});
    if (!auditoria.modulos.epis) auditoria.modulos.epis = { estado:"NO_INICIADO", controles:{} };
    if (!auditoria.modulos.radio) auditoria.modulos.radio = { estado:"NO_INICIADO", unidades:{} };
    // Una auditoría que contiene EPIs reales nunca se presenta como NO APLICA por pérdida de datos generales.
    const tieneEpis = auditoria.modulos.epis && auditoria.modulos.epis.controles && Object.values(auditoria.modulos.epis.controles).some(c => {
        if (!c) return false;
        if (c.unidades && typeof c.unidades === "object" && Object.keys(c.unidades).length) return true;
        const campos = c.campos || {};
        return Object.values(campos).some(v => String(v || "").trim()) || !!c.revisionFabricante;
    });
    if (tieneEpis && !auditoria.datosGenerales.actividad) auditoria.datosGenerales.actividad = "TELECOMUNICACIONES";
    if (tieneEpis && auditoria.modulos.epis.estado === "NO_APLICA") auditoria.modulos.epis.estado = "EN_CURSO";
    inicializarEpis();
    try { actualizarDashboard(); } catch (_) {}
}

/*
 * Recuperación V18 — flujo aislado y seguro.
 * IMPORTANTE: la recuperación nunca debe entrar en la pantalla "modulo".
 * Esa pantalla depende de una auditoría válida y, cuando la BBDD no devuelve
 * datos, podía provocar el bucle que impedía regresar al menú principal.
 */
let _recuperacionAuditoriaEnCurso = false;

function volverMenuPrincipalSeguro() {
    _recuperacionAuditoriaEnCurso = false;
    try {
        // Limpiamos únicamente la marca temporal de recuperación. No borramos
        // la auditoría actual por si el usuario estaba trabajando con otra.
        window._auditoriaRecuperada = false;
    } catch (_) {}

    try {
        mostrarPantalla("auditoriasInicio");
    } catch (e) {
        console.error("No se pudo mostrar el menú principal:", e);
        // Último recurso: quitar el estado active de todas las pantallas y
        // activar directamente el selector principal si existe.
        try {
            document.querySelectorAll(".screen").forEach(p => p.classList.remove("active"));
            const menu = document.getElementById("auditoriasInicio");
            if (menu) menu.classList.add("active");
        } catch (_) {}
    }
}

async function abrirAuditoriaRecuperada(id) {
    const auditoriaId = String(id || "").trim();
    if (!auditoriaId) {
        alert("Debe indicar un ID de auditoría.");
        return false;
    }

    if (_recuperacionAuditoriaEnCurso) return false;
    _recuperacionAuditoriaEnCurso = true;

    // NO usamos "modulo": la pantalla de recuperación es independiente de
    // una auditoría cargada y por tanto no puede bloquear la navegación.
    const contenedor = document.getElementById("dashboardEstadisticas");
    if (contenedor) {
        contenedor.innerHTML = `<div class="dashboard-header"><div><h2>Recuperar auditoría</h2><p>Recuperando <strong>${escapeHtml(auditoriaId)}</strong> desde la BBDD…</p></div><button type="button" class="secondary-button" onclick="volverMenuPrincipalSeguro()">← Menú principal</button></div><div class="card"><p>Consultando la BBDD…</p></div>`;
        mostrarPantalla("dashboardEstadisticas");
    }

    try {
        const data = await appGasGet({accion:"obtenerAuditoria", auditoriaId});
        if (!data || data.ok === false || !data.auditoria) {
            throw new Error((data && data.error) || "La BBDD no devolvió la auditoría solicitada.");
        }

        prepararAuditoriaRecuperada(data.auditoria);
        window._auditoriaRecuperada = true;
        _recuperacionAuditoriaEnCurso = false;

        try { actualizarDashboard(); } catch (e) { console.warn("Dashboard tras recuperación:", e); }
        try { instalarBotonMenuInicialVehiculos(); } catch (e) { console.warn("Botón menú inicial tras recuperación:", e); }
        mostrarPantalla("dashboard");
        alert("Auditoría " + auditoriaId + " recuperada correctamente desde la BBDD.");
        return true;
    } catch (e) {
        console.error("Error recuperando auditoría:", e);
        _recuperacionAuditoriaEnCurso = false;

        // CRÍTICO: ante cualquier error se abandona la pantalla de recuperación
        // y se vuelve directamente al menú principal. Nunca se reintenta de
        // forma automática ni se entra en el módulo de auditoría.
        volverMenuPrincipalSeguro();
        alert("No se ha podido recuperar la auditoría desde la BBDD.\n\n" + (e && e.message ? e.message : e));
        return false;
    }
}

async function recuperarAuditoriaPorId() {
    if (_recuperacionAuditoriaEnCurso) return;
    const id = prompt("Introduzca el ID de la auditoría que desea recuperar:", "");
    if (id === null) return;
    const auditoriaId = String(id || "").trim();
    if (!auditoriaId) {
        alert("Debe indicar un ID de auditoría.");
        return;
    }
    await abrirAuditoriaRecuperada(auditoriaId);
}


