async function generarDocumentoOficialRevisionEpi(claveEpi, idUnidad) {
    try {
        const definicion = obtenerEstructuraEpis()[claveEpi];
        if (!definicion) throw new Error("No se ha encontrado la definición del EPI.");
        const control = auditoria.modulos.epis && auditoria.modulos.epis.controles ? auditoria.modulos.epis.controles[claveEpi] : null;
        const unidad = definicion.multiple ? (control && control.unidades ? control.unidades[idUnidad] : null) : control;
        if (!unidad) throw new Error("No se ha encontrado el EPI que se desea documentar.");
        const campos = unidad.campos || {};
        const revision = unidad.revisionFabricante || {};
        const config = obtenerConfiguracionPlantillaFabricante(campos.marca || revision.fabricante || "", claveEpi);
        if (!config) throw new Error("No existe una plantilla oficial configurada para este fabricante y tipo de EPI.");
        if (config.plantillaClave === "IRUDEK_ARNES") {
            return await generarDocumentoRevisionIrudekArnes(claveEpi, idUnidad, definicion, unidad, campos, revision, config);
        }
        if (String(config.plantillaClave || "").indexOf("IRUDEK_") === 0) {
            return await generarDocumentoRevisionIrudekPlantillaOficial(claveEpi, idUnidad, definicion, unidad, campos, revision, config);
        }
        if (!revision.resultado) sincronizarVeredictoEpi(claveEpi, unidad, true);
        if (!revision.resultado) throw new Error("Debe indicar el veredicto de la revisión del fabricante antes de generar el documento.");
        const jsPDF = await cargarJsPdfLocal();
        const doc = new jsPDF({orientation:"p",unit:"mm",format:"a4"});
        const fuente = registrarFuentesSegoeUI(doc);
        const M=10, W=190; let y=15, pagina=1;
        const logo = typeof obtenerLogoFabricanteRevision === "function" ? obtenerLogoFabricanteRevision(config.fabricanteConfigurado || config.fabricanteNombre) : null;
        try { if (logo) doc.addImage(logo,"JPEG",160,6,35,12,"LOGO_EPI","FAST"); } catch (_) {}
        doc.setFont(fuente,"bold"); doc.setFontSize(13); doc.text("DOCUMENTO OFICIAL DE REVISIÓN EPI",M,y); y+=7;
        doc.setFont(fuente,"normal"); doc.setFontSize(8); doc.text(String(config.documentoOficial || config.tipoOficial || "Revisión de fabricante"),M,y); y+=5;
        doc.text("Auditoría: "+auditoria.id+"   ·   EPI: "+String(definicion.nombre||claveEpi),M,y); y+=5;
        doc.text("Fabricante: "+String(config.fabricanteNombre||campos.marca||"")+"   ·   Plantilla: "+String(config.plantillaClave||""),M,y); y+=5;
        doc.text("Norma: "+String(config.norma||"")+"   ·   Fecha revisión: "+String(revision.fechaRevision||obtenerFechaActual()),M,y); y+=8;
        const datos=[['Marca',campos.marca||'' ],['Modelo',campos.modelo||''],['Nº serie',campos.numeroSerie||campos.serie||''],['Fecha fabricación',campos.fechaFabricacion||''],['Verificado por',revision.verificadoPor||auditoria.datosGenerales.auditor||'']];
        const fila=(a,b)=>{doc.setDrawColor(120);doc.rect(M,y,50,6);doc.rect(M+50,y,140,6);doc.setFont(fuente,'bold');doc.setFontSize(7);doc.text(a,M+2,y+4);doc.setFont(fuente,'normal');doc.text(String(b||''),M+52,y+4);y+=6;};
        datos.forEach(x=>fila(x[0],x[1])); y+=4;
        doc.setFont(fuente,'bold');doc.setFontSize(8);doc.text('CONTROLES DE REVISIÓN',M,y);y+=5;
        const controles=config.controles||[];
        const mapa=revision.controles||{};
        controles.forEach(item=>{const clave=item[0], nombre=item[1]; const c=mapa[clave]||{}; const texto=clave+"  "+nombre+"  ["+(c.resultado||config.resultadoControlDefault||'')+"]"; const lines=doc.splitTextToSize(texto, W-4); const h=Math.max(6,lines.length*3.2+2); if(y+h>282){doc.setFont(fuente,'normal');doc.setFontSize(6);doc.text('Página '+pagina,105,291,{align:'center'});doc.addPage();pagina++;y=15;} doc.rect(M,y,W,h);doc.setFont(fuente,'normal');doc.setFontSize(6.4);doc.text(lines,M+2,y+4);y+=h;});
        y+=4; if(y>275){doc.addPage();pagina++;y=15;}
        doc.setFont(fuente,'bold');doc.setFontSize(9);doc.text('VEREDICTO: '+String(revision.resultado||''),M,y);y+=6;
        if(revision.comentarios){doc.setFont(fuente,'bold');doc.setFontSize(7);doc.text('Comentarios',M,y);y+=4;doc.setFont(fuente,'normal');const l=doc.splitTextToSize(String(revision.comentarios),W);doc.text(l,M,y);y+=l.length*3.2+4;}
        doc.setFont(fuente,'normal');doc.setFontSize(6);doc.text('Auditoría SPM Grupo Zener · '+auditoria.id, M,291);doc.text('Página '+pagina,200,291,{align:'right'});
        const blob=doc.output('blob');
        const nombre=(auditoria.id+'_'+String(definicion.nombre||claveEpi)+'_'+String(config.plantillaClave||'REVISION')+'.pdf').replace(/[^A-Za-z0-9áéíóúüñÁÉÍÓÚÜÑ._-]+/g,'_');
        const estado=document.getElementById('estadoDocumentoEpi_'+String(claveEpi).replace(/[^A-Za-z0-9_-]/g,'_')+'_'+String(idUnidad||'').replace(/[^A-Za-z0-9_-]/g,'_'));
        if(estado) estado.textContent='Generando y registrando documento en la BBDD…';
        const w=window.open('', '_blank');
        if(w){ w.document.write('<title>Documento oficial</title><p>Generando documento…</p>'); w.document.close(); }
        const res=await appGasPost({accion:'guardarInformePdf',auditoriaId:auditoria.id,tipo:'EPI_REVISION',nombre,mimeType:'application/pdf',base64:await blobADataUrl(blob),idEpi:claveEpi,unidadId:idUnidad||'',fabricante:config.fabricanteNombre||'',plantillaClave:config.plantillaClave||'',fechaRevision:revision.fechaRevision||obtenerFechaActual()});
        if(w){w.location.href=res.url || ('https://drive.google.com/uc?export=download&id='+res.fileId);}
        if(estado) estado.innerHTML='Documento oficial guardado correctamente. <button type="button" class="secondary-button" onclick="descargarUltimoDocumentoRevisionEpi(\''+String(claveEpi).replace(/'/g,"\\'")+ '\',\''+String(idUnidad||'').replace(/'/g,"\\'")+ '\')">📥 Descargar último documento</button>';
        alert('Documento oficial generado y guardado correctamente.');
        return res;
    } catch(e){ console.error(e); alert('No se ha podido generar el documento oficial.\n\n'+(e.message||e)); throw e; }
}


async function generarDocumentoRevisionIrudekPlantillaOficial(claveEpi, idUnidad, definicion, unidad, campos, revision, config) {
    /*
     * Generación fiel de las ocho fichas IRUDEK restantes.
     * El fondo es la propia plantilla oficial aportada por el usuario,
     * convertida a imagen A4. No se redibuja la maqueta con tablas genéricas.
     */
    const PLANTILLAS = {
        IRUDEK_ABSORBEDOR: {
            fondo: IRUDEK_TEMPLATE_ABSORBEDOR_JPG,
            filas: [1035,1058,1082,1106,1130,1153,1177,1201,1225,1248,1296,1320,1343],
            historico: 550, comentarios: [1396,1534], veredicto: 1534,
            cliente: [610,316,180], modelo: [610,396,180]
        },
        IRUDEK_ANTICAIDAS_DESLIZANTE: {
            fondo: IRUDEK_TEMPLATE_ANTICAIDAS_JPG,
            filas: [960,984,1008,1031,1055,1079,1150,1174,1198],
            historico: 544, comentarios: [1227,1364], veredicto: 1364,
            cliente: [685,344,105], modelo: [685,424,105]
        },
        IRUDEK_CASCO: {
            fondo: IRUDEK_TEMPLATE_CASCO_JPG,
            filas: [855,879,926,996,1020,1065,1091,1113],
            historico: 482, comentarios: [1118,1279], veredicto: 1279,
            cliente: [500,316,260], modelo: [500,396,260],
            historicoCampos: {fabricacionX: 294, compraX: 619, primerUsoX: 1020, serieX: 294, loteX: 619}
        },
        IRUDEK_CINTA_ANCLAJE: {
            fondo: IRUDEK_TEMPLATE_CINTA_JPG,
            filas: [1144,1168,1191,1215,1239],
            historico: 658, comentarios: [1268,1429], veredicto: 1429,
            cliente: [685,344,105], modelo: [685,424,105]
        },
        IRUDEK_CONECTOR: {
            fondo: IRUDEK_TEMPLATE_CONECTOR_JPG,
            filas: [939,963,987,1010],
            historico: 544, comentarios: [1085,1223], veredicto: 1223,
            cliente: [600,316,180], modelo: [600,396,180]
        },
        IRUDEK_CUERDA: {
            fondo: IRUDEK_TEMPLATE_CUERDA_JPG,
            filas: [996,1020,1044,1068,1091,1115,1186,1210,1234],
            historico: 510, comentarios: [1263,1400], veredicto: 1400,
            cliente: [600,344,180], modelo: [600,424,180]
        },
        IRUDEK_LINEA_VIDA_PORTATIL: {
            fondo: IRUDEK_TEMPLATE_LINEA_VIDA_JPG,
            // Coordenadas calibradas sobre la plantilla oficial IRUDEK de 1241x1754 px.
            // Las filas de los elementos metálicos empiezan inmediatamente después
            // de la línea de cabecera de sección.
            // Baselines centradas en las 7 filas reales de la tabla:
            // 4 textiles + 3 metálicas/funcionamiento.
            // Centros verticales reales de las 7 filas de control.
            // 4 textiles: 1138/1161/1185/1209
            // 3 metálicos: 1256/1280/1304
            // Baselines recalibradas con respecto a la línea base real de jsPDF.
            // Se colocan las X en el centro de cada una de las 7 celdas.
            filas: [1166,1190,1214,1238,1286,1310,1334],
            historico: 658, comentarios: [1363,1500], veredicto: 1500,
            cliente: [545,344,240], modelo: [545,440,240],
            bottom: { checkboxY: 1546, fechaY: 1582, verificadoY: 1609,
                      fechaX: 247, fechaW: 316, proximaX: 838, proximaW: 325,
                      verificadoX: 247, verificadoW: 916 }
        },
        IRUDEK_LAZO_SALVAMENTO: {
            fondo: IRUDEK_TEMPLATE_LAZO_JPG,
            filas: [1144,1168,1191,1215,1239],
            historico: 658, comentarios: [1268,1429], veredicto: 1429,
            cliente: [685,344,105], modelo: [685,424,105]
        }
    };

    const spec = PLANTILLAS[String(config.plantillaClave || "")];
    if (!spec) throw new Error("No existe la definición gráfica de la plantilla oficial IRUDEK: " + String(config.plantillaClave || ""));

    try {
        if (!revision.resultado) sincronizarVeredictoEpi(claveEpi, unidad, true);
        if (!revision.resultado) throw new Error("Debe indicar el veredicto de la revisión del fabricante antes de generar el documento.");

        const jsPDF = await cargarJsPdfLocal();
        const doc = new jsPDF({orientation:"p", unit:"mm", format:"a4"});
        const fuente = registrarFuentesSegoeUI(doc);

        const SX = 210 / 1241;
        const SY = 297 / 1754;
        const px = v => v * SX;
        const py = v => v * SY;

        const texto = (s, x, y, fs=8, bold=false) => {
            const value = String(s == null ? "" : s).trim();
            if (!value) return;
            doc.setFont(fuente, bold ? "bold" : "normal");
            doc.setFontSize(fs);
            doc.text(value, px(x), py(y));
        };

        const borrar = (x,y,w,h) => {
            doc.setFillColor(255,255,255);
            doc.rect(px(x), py(y), px(w), py(h), "F");
        };

        const marcar = (x,y) => {
            doc.setFont(fuente,"bold");
            doc.setFontSize(6.5);
            doc.text("X", px(x), py(y), {align:"center"});
        };

        doc.addImage(spec.fondo, "JPEG", 0, 0, 210, 297, "IRUDEK_"+String(config.plantillaClave), "FAST");

        // La plantilla original divide "PORTÁTIL" en PORTATI + L por el ajuste
        // de la imagen. Para la ficha oficial de LÍNEA DE VIDA PORTÁTIL se
        // reconstruye únicamente esta zona gráfica, sin tocar el resto de la
        // plantilla: LÍNEA / DE VIDA / PORTÁTIL, cada palabra en su línea.
        if (String(config.plantillaClave || "") === "IRUDEK_LINEA_VIDA_PORTATIL") {
            doc.setFillColor(255,255,255);
            doc.rect(px(58), py(330), px(315), py(315), "F");
            doc.setTextColor(0,0,0);
            doc.setFont("times","bold");
            doc.setFontSize(22);
            doc.text("LÍNEA", px(205), py(401), {align:"center"});
            doc.text("DE VIDA", px(205), py(480), {align:"center"});
            doc.text("PORTÁTIL", px(205), py(559), {align:"center"});
        }

        const dg = auditoria.datosGenerales || {};
        const cliente = dg.cliente || dg.empresa || "";
        const modelo = campos.modelo || "";

        // Cabecera: las plantillas oficiales no tienen una celda para el dato;
        // el valor debe comenzar DESPUÉS del rótulo CLIENTE/MODELO.
        // La coordenada anterior [685,...] desplazaba el dato demasiado a la derecha.
        const textoCabeceraLimitado = (valor, pos, fs=7.2) => {
            const value = String(valor == null ? "" : valor).replace(/\s+/g, " ").trim();
            if (!value) return;
            doc.setFont(fuente, "normal");
            doc.setFontSize(fs);
            const maxWidth = px(pos[2]);
            let out = value;
            while (out.length > 1 && doc.getTextWidth(out) > maxWidth) out = out.slice(0,-1);
            if (out.length < value.length && out.length > 3) out = out.slice(0,-3) + "…";
            doc.text(out, px(pos[0]), py(pos[1] + 12));
        };
        textoCabeceraLimitado(cliente, spec.cliente);
        textoCabeceraLimitado(modelo, spec.modelo);

        // Verificación histórica: las celdas de valor de la plantilla oficial
        // comienzan aproximadamente en X=359, 669 y 1042 px.
        // Se escribe dentro de esas celdas, nunca sobre el rótulo.
        const hy = spec.historico;
        const fechaFabricacion = formatearFechaDocumentoIrudek(campos.fechaFabricacion);
        const fechaCompra = formatearFechaDocumentoIrudek(campos.fechaCompra);
        const fechaPrimerUso = formatearFechaDocumentoIrudek(campos.fechaPrimerUso);
        const numeroSerie = campos.numeroSerie || campos.serie || "";
        const numeroLote = campos.numeroLote || "";

        // Aunque la plantilla rotula "Año de fabricación", la aplicación
        // dispone de la fecha completa. Se muestra completa en formato
        // DD/MM/YYYY para no convertir 2025-04-01 en el erróneo "04-01".
        const hc = spec.historicoCampos || {};
        texto(fechaFabricacion, hc.fabricacionX ?? 370, hy+38, 8);
        texto(fechaCompra, hc.compraX ?? 685, hy+38, 8);
        texto(fechaPrimerUso, hc.primerUsoX ?? 1050, hy+38, 8);
        texto(textoDocumentoIrudek(numeroSerie,22), hc.serieX ?? 370, hy+62, 8);
        texto(textoDocumentoIrudek(numeroLote,22), hc.loteX ?? 685, hy+62, 8);

        // Las fichas oficiales IRUDEK usan B / AV / R / M / NP.
        const colX = {B:873, AV:930, R:995, M:1068, NP:1134};
        const controles = config.controles || [];
        const mapa = revision.controles || {};
        controles.forEach((item, i) => {
            const y = spec.filas[i];
            if (y == null) return;
            const c = mapa[item[0]] || {};
            let r = String(c.resultado || config.resultadoControlDefault || "B").trim().toUpperCase();
            if (r === "CORRECTO") r = "B";
            if (r === "INCORRECTO") r = "M";
            if (r === "NO_PROCEDE") r = "NP";
            if (!Object.prototype.hasOwnProperty.call(colX, r)) r = "B";
            marcar(colX[r], y);
        });

        // Comentarios dentro del área exacta de la ficha.
        const commentsTop = spec.comentarios[0] + 4;
        const commentsBottom = spec.comentarios[1] - 5;
        borrar(60, commentsTop, 1090, Math.max(20, commentsBottom-commentsTop));
        const comentarios = String(revision.comentarios || "").trim();
        if (comentarios) {
            doc.setFont(fuente,"normal");
            doc.setFontSize(7.3);
            const lines = doc.splitTextToSize(comentarios, px(1045));
            const maxLines = Math.max(1, Math.floor((commentsBottom-commentsTop-12)/10));
            doc.text(lines.slice(0,maxLines), px(72), py(commentsTop+18));
        }

        // Veredicto y datos finales: las casillas están en la fila de opciones,
        // mientras que fecha/verificador ocupan filas independientes debajo.
        // Nunca se borra la fila del texto oficial "El producto es APTO...".
        const bottom = spec.bottom || {
            checkboxY: spec.veredicto + 46,
            fechaY: spec.veredicto + 81,
            verificadoY: spec.veredicto + 105,
            fechaX: 247, fechaW: 316, proximaX: 838, proximaW: 325,
            verificadoX: 247, verificadoW: 916
        };
        const resultado = String(revision.resultado || "").toUpperCase();
        if (resultado.includes("NO APTO")) marcar(1148, bottom.checkboxY);
        else marcar(638, bottom.checkboxY);

        // Limpiar exclusivamente las celdas de datos, respetando todos los textos
        // y bordes originales de la plantilla.
        borrar(bottom.fechaX, bottom.fechaY-11, bottom.fechaW, 22);
        borrar(bottom.proximaX, bottom.fechaY-11, bottom.proximaW, 22);
        borrar(bottom.verificadoX, bottom.verificadoY-11, bottom.verificadoW, 22);

        texto(formatearFechaDocumentoIrudek(revision.fechaRevision || obtenerFechaActual()), 259, bottom.fechaY+4, 8);
        // La celda de "Fecha próxima revisión" empieza DESPUÉS del rótulo,
        // aproximadamente en X=838. Nunca se debe escribir desde X=669
        // porque esa zona pertenece al texto fijo "Fecha próxima revisión:".
        const proximaRevision = formatearFechaDocumentoIrudek(
            obtenerFechaProximaRevisionDocumentoIrudek(revision)
        );
        if (proximaRevision) {
            texto(proximaRevision, 850, bottom.fechaY+4, 8);
        }
        texto(textoDocumentoIrudek(revision.verificadoPor || dg.auditor || "",80), 259, bottom.verificadoY+4, 8);

        // Firma del auditor, si está disponible.
        const firma = auditoria.firmas && (auditoria.firmas.auditor || auditoria.firmas.firmaAuditor);
        if (firma) {
            try {
                const p = doc.getImageProperties(firma);
                let w = 52, h = w / (p.width / p.height);
                if (h > 20) { h = 20; w = h * (p.width / p.height); }
                const firmaY = (spec.bottom && spec.bottom.verificadoY ? spec.bottom.verificadoY + 30 : spec.veredicto + 134);
                doc.addImage(firma, undefined, px(191), py(firmaY), px(w / SX), py(h / SY), undefined, "FAST");
            } catch (_) {}
        }

        const blob = doc.output("blob");
        const nombre = (auditoria.id+"_"+String(definicion.nombre||claveEpi)+"_"+String(config.plantillaClave||"REVISION")+".pdf")
            .replace(/[^A-Za-z0-9áéíóúüñÁÉÍÓÚÜÑ._-]+/g,"_");

        const estado = document.getElementById(
            "estadoDocumentoEpi_"+String(claveEpi).replace(/[^A-Za-z0-9_-]/g,"_")+"_"+String(idUnidad||"").replace(/[^A-Za-z0-9_-]/g,"_")
        );
        if (estado) estado.textContent = "Generando y registrando documento oficial IRUDEK en la BBDD…";

        const w = window.open("", "_blank");
        if (w) {
            w.document.write("<title>Revisión oficial IRUDEK</title><p>Generando documento oficial…</p>");
            w.document.close();
        }

        const res = await appGasPost({
            accion:"guardarInformePdf",
            auditoriaId:auditoria.id,
            tipo:"EPI_REVISION",
            nombre,
            mimeType:"application/pdf",
            base64:await blobADataUrl(blob),
            idEpi:claveEpi,
            unidadId:idUnidad||"",
            fabricante:"IRUDEK",
            plantillaClave:config.plantillaClave||"",
            fechaRevision:revision.fechaRevision||obtenerFechaActual()
        });

        if (w) w.location.href = res.url || ("https://drive.google.com/uc?export=download&id="+res.fileId);
        if (estado) estado.innerHTML =
            "Documento oficial IRUDEK generado y guardado correctamente. <button type=\"button\" class=\"secondary-button\" onclick=\"descargarUltimoDocumentoRevisionEpi('"+
            String(claveEpi).replace(/'/g,"\\'")+"','"+String(idUnidad||"").replace(/'/g,"\\'")+
            "')\">📥 Descargar último documento</button>";

        alert("Documento oficial IRUDEK generado y guardado correctamente.");
        return res;
    } catch (e) {
        console.error(e);
        alert("No se ha podido generar el documento oficial IRUDEK.\n\n"+(e.message||e));
        throw e;
    }
}

function formatearFechaDocumentoIrudek(valor) {
    const s = String(valor || "").trim();
    if (!s) return "";
    const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (m) return m[3] + "/" + m[2] + "/" + m[1];
    return s;
}

function textoDocumentoIrudek(valor, max=42) {
    return String(valor == null ? "" : valor).replace(/\s+/g, " ").trim().slice(0, max);
}

function obtenerFechaProximaRevisionDocumentoIrudek(revision) {
    const indicada = String(revision && revision.fechaProximaRevision || "").trim();
    if (indicada) return indicada;
    const base = String(revision && revision.fechaRevision || "").trim() || obtenerFechaActual();
    const m = base.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!m) return "";
    const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
    if (Number.isNaN(d.getTime())) return "";
    d.setFullYear(d.getFullYear() + 1);
    return d.getFullYear() + "-" +
        String(d.getMonth() + 1).padStart(2, "0") + "-" +
        String(d.getDate()).padStart(2, "0");
}

async function generarDocumentoRevisionIrudekArnes(claveEpi, idUnidad, definicion, unidad, campos, revision, config) {
    try {
        if (!revision.resultado) sincronizarVeredictoEpi(claveEpi, unidad, true);
        if (!revision.resultado) throw new Error("Debe indicar el veredicto de la revisión del fabricante antes de generar el documento.");
        const jsPDF = await cargarJsPdfLocal();
        const doc = new jsPDF({ orientation: "p", unit: "mm", format: "a4" });
        const fuente = registrarFuentesSegoeUI(doc);
        const SX = 210 / 1241, SY = 297 / 1754;
        const px = v => v * SX;
        const py = v => v * SY;
        const texto = (s, x, y, fs=8, bold=false, opts={}) => {
            doc.setFont(fuente, bold ? "bold" : "normal");
            doc.setFontSize(fs);
            doc.text(String(s || ""), px(x), py(y), opts);
        };
        const borrar = (x,y,w,h) => { doc.setFillColor(255,255,255); doc.rect(px(x),py(y),px(w),py(h),"F"); };
        const marcar = (x,y) => { doc.setFont(fuente,"bold"); doc.setFontSize(7.5); doc.text("X",px(x),py(y),{align:"center"}); };

        // Fondo exacto de la plantilla oficial convertida a A4.
        doc.addImage(IRUDEK_ARNES_TEMPLATE_JPG, "PNG", 0, 0, 210, 297, "IRUDEK_ARNES_TEMPLATE", "FAST");

        const dg = auditoria.datosGenerales || {};
        const cliente = dg.cliente || dg.empresa || "";
        const modelo = campos.modelo || "";
        const fechaFabricacion = formatearFechaDocumentoIrudek(campos.fechaFabricacion);
        const fechaCompra = formatearFechaDocumentoIrudek(campos.fechaCompra);
        const fechaPrimerUso = formatearFechaDocumentoIrudek(campos.fechaPrimerUso);
        const numeroSerie = campos.numeroSerie || campos.serie || "";
        const numeroLote = campos.numeroLote || "";

        // Cabecera: solo se rellenan las zonas que en la plantilla son campos vacíos.
        texto(textoDocumentoIrudek(cliente,45), 455, 304, 8.8, false);
        texto(textoDocumentoIrudek(modelo,38), 455, 375, 8.8, false);

        // Verificación histórica.
        texto(fechaFabricacion, 294, 486, 8, false);
        texto(fechaCompra, 619, 486, 8, false);
        texto(fechaPrimerUso, 994, 486, 8, false);
        texto(textoDocumentoIrudek(numeroSerie,22), 294, 510, 8, false);
        texto(textoDocumentoIrudek(numeroLote,22), 619, 510, 8, false);

        // Marcas de los 16 controles en las casillas B / AV / R / M / NP.
        const colX = { B:873, AV:930, R:995.3, M:1068.1, NP:1135.6 };
        const filasY = [890.6,914.6,937.9,961.9,985.9,1009.1,1033.1,1057.1,1127.6,1174.8,1198.1,1222.1,1246.1,1293.3,1317.3,1341.3];
        const controles = config.controles || [];
        const mapa = revision.controles || {};
        controles.forEach((item, i) => {
            const c = mapa[item[0]] || {};
            let r = String(c.resultado || config.resultadoControlDefault || "B").trim().toUpperCase();
            if (r === "CORRECTO") r = "B";
            if (r === "NO_PROCEDE") r = "NP";
            if (r === "INCORRECTO") r = "M";
            if (!Object.prototype.hasOwnProperty.call(colX, r)) r = "B";
            if (filasY[i] != null) marcar(colX[r], filasY[i]);
        });

        // Comentarios: se conserva exactamente el marco y el rótulo de la plantilla.
        borrar(58.5,1370.8,1102.9,132);
        const comentarios = String(revision.comentarios || "").trim();
        if (comentarios) {
            doc.setFont(fuente,"normal");
            doc.setFontSize(7.3);
            const lines = doc.splitTextToSize(comentarios, px(1058));
            doc.text(lines.slice(0,18), px(71), py(1387));
        }

        // Veredicto: se marcan las casillas originales de la plantilla.
        const resultado = String(revision.resultado || "").toUpperCase();
        if (resultado.includes("NO APTO")) marcar(594.2,1520.8);
        else marcar(1104.4,1520.8);

        // Fecha de revisión, próxima revisión y verificador.
        borrar(251.5,1531.2,263,39);
        borrar(794.5,1531.2,323,39);
        borrar(251.5,1577,866,20.3);
        texto(formatearFechaDocumentoIrudek(revision.fechaRevision || obtenerFechaActual()), 289, 1554, 8, false);
        texto(formatearFechaDocumentoIrudek(revision.fechaProximaRevision || ""), 818, 1554, 8, false);
        texto(textoDocumentoIrudek(revision.verificadoPor || dg.auditor || "",80), 262, 1592, 8, false);

        // Firma del auditor si existe en la auditoría recuperada.
        const firma = auditoria.firmas && (auditoria.firmas.auditor || auditoria.firmas.firmaAuditor);
        if (firma) {
            try {
                const p = doc.getImageProperties(firma);
                let w = 52, h = w / (p.width / p.height);
                if (h > 20) { h = 20; w = h * (p.width / p.height); }
                doc.addImage(firma, undefined, px(191), py(1626), px(w / SX), py(h / SY), undefined, "FAST");
            } catch (_) {}
        }

        doc.setFont(fuente,"normal");
        doc.setFontSize(5.8);
        doc.text("Documento generado desde la plantilla oficial IRUDEK · Auditoría SPM Grupo Zener · " + String(auditoria.id || ""), 105, 293.5, {align:"center"});

        const blob = doc.output("blob");
        const nombre = (auditoria.id + "_ARNES_IRUDEK_FICHA_VERIFICACION_EPI.pdf").replace(/[^A-Za-z0-9áéíóúüñÁÉÍÓÚÜÑ._-]+/g,"_");
        const estado = document.getElementById("estadoDocumentoEpi_"+String(claveEpi).replace(/[^A-Za-z0-9_-]/g,"_")+"_"+String(idUnidad||"").replace(/[^A-Za-z0-9_-]/g,"_"));
        if (estado) estado.textContent = "Generando y registrando documento oficial IRUDEK en la BBDD…";
        const w = window.open("", "_blank");
        if (w) { w.document.write("<title>Revisión IRUDEK — Arnés</title><p>Generando documento oficial…</p>"); w.document.close(); }
        const res = await appGasPost({
            accion:"guardarInformePdf",
            auditoriaId:auditoria.id,
            tipo:"EPI_REVISION",
            nombre,
            mimeType:"application/pdf",
            base64:await blobADataUrl(blob),
            idEpi:claveEpi,
            unidadId:idUnidad||"",
            fabricante:"IRUDEK",
            plantillaClave:"IRUDEK_ARNES",
            fechaRevision:revision.fechaRevision||obtenerFechaActual()
        });
        if (w) w.location.href = res.url || ("https://drive.google.com/uc?export=download&id="+res.fileId);
        if (estado) estado.innerHTML = "Documento oficial IRUDEK generado y guardado correctamente. <button type=\"button\" class=\"secondary-button\" onclick=\"descargarUltimoDocumentoRevisionEpi('"+String(claveEpi).replace(/'/g,"\\'")+"','"+String(idUnidad||"").replace(/'/g,"\\'")+"')\">📥 Descargar último documento</button>";
        alert("Documento oficial IRUDEK de revisión de arnés generado y guardado correctamente.");
        return res;
    } catch(e) {
        console.error(e);
        alert("No se ha podido generar el documento oficial IRUDEK de revisión de arnés.\
\
"+(e.message||e));
        throw e;
    }
}

async function descargarUltimoDocumentoRevisionEpi(claveEpi,idUnidad) {
    try {
        const r=await appGasGet({accion:'obtenerDocumentoEpi',auditoriaId:auditoria.id,idEpi:claveEpi,unidadId:idUnidad||''});
        if(!r.encontrado) { alert('No existe todavía un documento oficial para este EPI. Genérelo primero.'); return; }
        const url=r.url || (r.fileId ? 'https://drive.google.com/uc?export=download&id='+r.fileId : '');
        if(!url) throw new Error('La BBDD no contiene una referencia válida al documento.');
        window.open(url,'_blank','noopener');
    } catch(e){ alert('No se ha podido recuperar el documento oficial desde la BBDD.\n\n'+(e.message||e)); }
}

function obtenerLogoFabricanteRevision(fabricante){
    const f=normalizarFabricante(fabricante||'');
    if(f==='IRUDEK' && typeof LOGO_EPI_IRUDEK_JPG!=='undefined') return LOGO_EPI_IRUDEK_JPG;
    if(f==='PATACHO' && typeof LOGO_EPI_PATACHO_JPG!=='undefined') return LOGO_EPI_PATACHO_JPG;
    if(f==='MIGUEL_MIRANDA' && typeof LOGO_EPI_MIGUEL_MIRANDA_JPG!=='undefined') return LOGO_EPI_MIGUEL_MIRANDA_JPG;
    if(f==='CLIMAX' && typeof LOGO_EPI_CLIMAX_JPG!=='undefined') return LOGO_EPI_CLIMAX_JPG;
    return null;
}

/* V18: las constantes de logos se incorporarán desde la versión de plantillas oficiales cuando estén disponibles. */
